import { createFileRoute } from "@tanstack/react-router";
import { useMemo, useState } from "react";
import {
  Activity, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Bell, BookOpen,
  BrainCircuit, BriefcaseBusiness, Building2, Check, ChevronDown, ChevronLeft,
  ChevronRight, CircleHelp, ClipboardList, Clock3, Code2, Download, FileText,
  Gauge, GraduationCap, LayoutDashboard, Menu, MessageSquareText, Mic2, Plus,
  Search, Settings2, ShieldCheck, Sparkles, Target, TrendingUp, Users, WandSparkles,
  X, Zap,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";

export const Route = createFileRoute("/")({
  head: () => ({
    meta: [
      { title: "MOCKMATE — AI Placement Prep" },
      { name: "description", content: "Practice company interviews, review demo feedback, and plan your placement preparation with MOCKMATE." },
      { property: "og:title", content: "MOCKMATE — AI Placement Prep" },
      { property: "og:description", content: "A company-smart interview practice and placement preparation workspace." },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary_large_image" },
    ],
  }),
  component: App,
});

type Page = "Dashboard" | "New Interview" | "Coaching" | "Reports" | "Under the Hood" | "Settings" | "Interview Room" | "Evaluation";
type InterviewConfig = { company: string; role: string; difficulty: string; count: string };
type Session = { question: string; answer: string; score: number };

const navItems: { name: Page; icon: typeof LayoutDashboard }[] = [
  { name: "Dashboard", icon: LayoutDashboard }, { name: "New Interview", icon: Plus },
  { name: "Coaching", icon: WandSparkles }, { name: "Reports", icon: ClipboardList },
  { name: "Under the Hood", icon: BrainCircuit },
];
const companies = ["Google", "Amazon", "Microsoft", "Infosys", "TCS", "Accenture"];
const roles = ["Software Developer", "Data Analyst", "Web Developer", "AI/ML Engineer"];
const questionBank = [
  "Tell me about a technical project you're proud of. What was the most challenging part?",
  "How would you design a URL shortener that handles millions of requests per day?",
  "Describe a time you had to debug a difficult issue. How did you approach it?",
  "What is the difference between a process and a thread? When would you use each?",
  "How do you make sure an API remains reliable as its usage grows?",
  "Tell me about a time you received feedback and what you changed as a result.",
  "How would you find the first non-repeating character in a string?",
  "What trade-offs would you consider when choosing between SQL and NoSQL?",
  "Walk me through how you would test a feature before shipping it.",
  "What would you like to learn in your first six months in this role?",
];
const sessions = [
  { company: "Google", role: "Software Developer", date: "Today, 10:42 AM", score: 8.4, tag: "Technical" },
  { company: "Amazon", role: "Web Developer", date: "Yesterday", score: 7.6, tag: "Behavioral" },
  { company: "Microsoft", role: "AI/ML Engineer", date: "Oct 18, 2025", score: 8.1, tag: "Mixed" },
];
const architecture = [
  { step: "01", title: "Intent Router", detail: "Classifies PRACTICE, EVALUATE, COACH, REPORT, or OTHER.", icon: Zap },
  { step: "02", title: "Retrieval Planner", detail: "Plans which context and feedback signals are relevant.", icon: Search },
  { step: "03", title: "ChromaDB", detail: "Vector store for interview material and prior feedback.", icon: Building2 },
  { step: "04", title: "AI Agents", detail: "Specialists coordinate a focused response.", icon: BrainCircuit },
];

function App() {
  const [page, setPage] = useState<Page>("Dashboard");
  const [mobileOpen, setMobileOpen] = useState(false);
  const [config, setConfig] = useState<InterviewConfig>({ company: "", role: "", difficulty: "Mixed", count: "5" });
  const [questionIndex, setQuestionIndex] = useState(0);
  const [answer, setAnswer] = useState("");
  const [history, setHistory] = useState<Session[]>([]);
  const [selectedEval, setSelectedEval] = useState<Session | null>(null);
  const [error, setError] = useState("");
  const [toast, setToast] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const currentQuestion = questionBank[questionIndex % questionBank.length];
  const answersCount = history.length;
  const navTo = (next: Page) => { setPage(next); setMobileOpen(false); setToast(""); };
  const startInterview = () => {
    if (!config.company || !config.role) { setError("Choose a company and role to continue."); return; }
    setError(""); setQuestionIndex(0); setAnswer(""); setHistory([]); navTo("Interview Room");
  };
  const submitAnswer = () => {
    if (!answer.trim()) { setError("Add an answer before submitting."); return; }
    const score = 6 + (answer.trim().length % 35) / 10;
    const submitted = { question: currentQuestion, answer: answer.trim(), score: Math.min(9.4, Number(score.toFixed(1))) };
    setHistory((prev) => [...prev, submitted]); setSelectedEval(submitted); setAnswer(""); setError(""); navTo("Evaluation");
  };
  const nextQuestion = () => {
    if (answersCount >= Number(config.count)) { navTo("Reports"); return; }
    setQuestionIndex((value) => value + 1); setSelectedEval(null); setError(""); navTo("Interview Room");
  };
  const finishInterview = () => {
    if (history.length) navTo("Reports"); else navTo("Dashboard");
  };

  return (
    <div className="min-h-screen bg-background text-foreground">
      <aside className={`fixed inset-y-0 left-0 z-40 flex w-[260px] flex-col border-r border-sidebar-border bg-sidebar transition-transform duration-200 md:translate-x-0 ${mobileOpen ? "translate-x-0" : "-translate-x-full"}`}>
        <div className="flex h-[76px] items-center justify-between border-b border-sidebar-border px-6">
          <button aria-label="Go to dashboard" onClick={() => navTo("Dashboard")} className="flex items-center gap-3 text-left">
            <span className="flex size-9 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-glow"><BrainCircuit size={20} /></span>
            <span><span className="block text-[15px] font-extrabold tracking-[0.06em]">MOCKMATE</span><span className="mt-0.5 block text-[11px] text-muted-foreground">AI Placement Prep</span></span>
          </button>
          <Button aria-label="Close navigation" variant="ghost" size="icon" className="md:hidden" onClick={() => setMobileOpen(false)}><X /></Button>
        </div>
        <div className="px-4 pt-6"><p className="mb-3 px-3 text-[10px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">Workspace</p>
          <nav className="space-y-1" aria-label="Main navigation">{navItems.map(({ name, icon: Icon }) => <NavItem key={name} name={name} icon={Icon} active={page === name} onClick={() => navTo(name)} />)}</nav>
        </div>
        <div className="mt-7 px-4"><p className="mb-3 px-3 text-[10px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">Account</p><NavItem name="Settings" icon={Settings2} active={page === "Settings"} onClick={() => navTo("Settings")} /></div>
        <div className="mt-auto border-t border-sidebar-border p-4">
          <div className="flex items-center gap-3 rounded-xl px-2 py-2"><div className="flex size-9 shrink-0 items-center justify-center rounded-full bg-accent text-sm font-bold text-accent-foreground">S</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">Student</p><p className="truncate text-xs text-muted-foreground">Engineering Student</p></div><ChevronDown size={16} className="text-muted-foreground" /></div>
        </div>
      </aside>
      {mobileOpen && <button aria-label="Close navigation overlay" className="fixed inset-0 z-30 bg-background/70 md:hidden" onClick={() => setMobileOpen(false)} />}
      <div className="min-h-screen md:pl-[260px]">
        <header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-border bg-background/90 px-4 backdrop-blur-md sm:px-8">
          <div className="flex min-w-0 items-center gap-3"><Button aria-label="Open navigation" variant="ghost" size="icon" className="md:hidden" onClick={() => setMobileOpen(true)}><Menu /></Button><div className="min-w-0"><p className="truncate text-[11px] text-muted-foreground">Workspace <span className="mx-1.5">/</span> <span className="text-foreground">{page}</span></p><h1 className="mt-0.5 truncate text-base font-semibold">{page === "Interview Room" ? "Interview in progress" : page === "Evaluation" ? "Answer evaluation" : page}</h1></div></div>
          <div className="flex items-center gap-2"><span className="hidden items-center gap-1.5 rounded-full border border-border px-2.5 py-1 text-[10px] font-semibold text-warning sm:flex"><span className="size-1.5 rounded-full bg-warning" /> DEMO MODE</span><Button aria-label="Notifications" variant="ghost" size="icon" className="relative"><Bell /><span className="absolute right-2 top-2 size-1.5 rounded-full bg-primary" /></Button><div className="ml-1 flex size-8 items-center justify-center rounded-full bg-accent text-xs font-bold text-accent-foreground">S</div></div>
        </header>
        <main className="mx-auto max-w-[1450px] px-4 py-7 sm:px-8 sm:py-9">
          {page === "Dashboard" && <Dashboard onNew={() => navTo("New Interview")} onPage={navTo} />}
          {page === "New Interview" && <NewInterview config={config} setConfig={setConfig} error={error} onStart={startInterview} />}
          {page === "Interview Room" && <InterviewRoom config={config} question={currentQuestion} questionNumber={answersCount + 1} total={Number(config.count)} answer={answer} setAnswer={setAnswer} error={error} history={history} onSubmit={submitAnswer} onSkip={nextQuestion} onEnd={finishInterview} />}
          {page === "Evaluation" && <Evaluation session={selectedEval} config={config} questionNumber={answersCount} total={Number(config.count)} onNext={nextQuestion} />}
          {page === "Coaching" && <Coaching onReports={() => navTo("Reports")} />}
          {page === "Reports" && <Reports config={config} history={history} searchTerm={searchTerm} setSearchTerm={setSearchTerm} toast={toast} setToast={setToast} />}
          {page === "Under the Hood" && <UnderTheHood />}
          {page === "Settings" && <Settings />}
        </main>
      </div>
    </div>
  );
}

function NavItem({ name, icon: Icon, active, onClick }: { name: string; icon: typeof LayoutDashboard; active: boolean; onClick: () => void }) {
  return <Button variant="ghost" onClick={onClick} aria-current={active ? "page" : undefined} className={`h-10 w-full justify-start gap-3 rounded-lg px-3 text-[13px] ${active ? "bg-sidebar-accent text-sidebar-accent-foreground hover:bg-sidebar-accent" : "text-muted-foreground hover:text-foreground"}`}><Icon size={17} /><span>{name}</span>{name === "New Interview" && <span className="ml-auto rounded bg-primary/20 px-1.5 py-0.5 text-[9px] font-semibold text-primary">NEW</span>}</Button>;
}
function SectionHeading({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: React.ReactNode }) {
  return <div className="mb-6 flex flex-wrap items-end justify-between gap-3"><div>{eyebrow && <p className="mb-2 text-[10px] font-bold uppercase tracking-[0.17em] text-primary">{eyebrow}</p>}<h2 className="text-xl font-semibold tracking-tight sm:text-2xl">{title}</h2></div>{action}</div>;
}
function DemoTag() { return <Badge variant="outline" className="border-warning/30 bg-warning/10 text-warning">DEMO DATA</Badge>; }
function Dashboard({ onNew, onPage }: { onNew: () => void; onPage: (page: Page) => void }) {
  const stats = [{ label: "Total interviews", value: "12", delta: "+3 this month", icon: BriefcaseBusiness, color: "text-primary", trend: "up" }, { label: "Average score", value: "7.8", delta: "+0.6 vs. last month", icon: Gauge, color: "text-success", trend: "up" }, { label: "Questions practiced", value: "48", delta: "Across 6 companies", icon: MessageSquareText, color: "text-chart-4", trend: "up" }, { label: "Improvement", value: "+18%", delta: "Over 30 days", icon: TrendingUp, color: "text-warning", trend: "up" }];
  return <div className="space-y-8">
    <div className="relative overflow-hidden rounded-2xl border border-border bg-card p-6 shadow-card sm:p-8"><div className="absolute right-0 top-0 hidden h-full w-[38%] border-l border-border/60 bg-gradient-to-br from-primary/10 via-transparent to-chart-4/5 lg:block" /><div className="relative z-10 max-w-2xl"><div className="mb-4 flex flex-wrap items-center gap-2"><Badge className="border-primary/20 bg-primary/15 text-primary hover:bg-primary/15"><Sparkles size={12} className="mr-1" /> Placement season ready</Badge><DemoTag /></div><h2 className="text-3xl font-semibold leading-tight tracking-tight sm:text-[38px]">Prepare smarter.<br className="hidden sm:block" /> Interview better.</h2><p className="mt-3 max-w-lg text-sm leading-6 text-muted-foreground">Your personal AI-powered company interview coach. Build confidence, one practice session at a time.</p><Button onClick={onNew} size="lg" className="mt-6 h-11 gap-2 shadow-glow"><Plus size={17} /> Start new interview <ArrowRight size={16} /></Button></div><div className="absolute bottom-5 right-7 hidden items-center gap-2 text-xs text-muted-foreground lg:flex"><span className="size-2 rounded-full bg-success" /> 5-day prep streak</div></div>
    <div className="grid grid-cols-1 gap-3 min-[480px]:grid-cols-2 xl:grid-cols-4">{stats.map(({ label, value, delta, icon: Icon, color }) => <div key={label} className="surface p-4 sm:p-5"><div className="flex items-center justify-between"><span className="text-[12px] text-muted-foreground">{label}</span><Icon size={17} className={color} /></div><div className="mt-4 flex items-end justify-between gap-2"><span className="text-[26px] font-semibold leading-none">{value}</span><span className="flex items-center gap-1 text-[10px] text-success"><ArrowUpRight size={13} />{delta}</span></div></div>)}</div>
    <div className="grid gap-5 xl:grid-cols-[1.4fr_0.9fr]">
      <section className="surface min-w-0 p-5 sm:p-6"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-sm font-semibold">Recent interviews</h3><p className="mt-1 text-xs text-muted-foreground">Your latest practice sessions</p></div><Button variant="ghost" size="sm" onClick={() => onPage("Reports")} className="gap-1 text-xs text-primary">View all <ArrowRight size={14} /></Button></div><div className="space-y-1">{sessions.map((session, i) => <div key={session.company} className="flex flex-wrap items-center gap-3 border-t border-border/70 py-3.5"><div className={`flex size-9 shrink-0 items-center justify-center rounded-lg text-xs font-bold ${i === 0 ? "bg-primary/15 text-primary" : i === 1 ? "bg-chart-4/15 text-chart-4" : "bg-success/15 text-success"}`}>{session.company.slice(0, 1)}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{session.company} <span className="text-muted-foreground">·</span> {session.role}</p><p className="mt-1 text-[11px] text-muted-foreground">{session.date} <span className="mx-1">·</span>{session.tag}</p></div><div className="flex items-center gap-2"><span className="text-sm font-semibold">{session.score}</span><span className="text-[10px] text-muted-foreground">/10</span><ChevronRight size={15} className="text-muted-foreground" /></div></div>)}</div><div className="mt-3 flex items-center gap-2 rounded-lg bg-warning/10 px-3 py-2 text-[11px] leading-5 text-warning"><CircleHelp size={14} className="shrink-0" /> Sample sessions show how your history will look.</div></section>
      <section className="surface p-5 sm:p-6"><div className="flex items-start justify-between"><div><h3 className="text-sm font-semibold">Performance overview</h3><p className="mt-1 text-xs text-muted-foreground">Average score · last 6 sessions</p></div><Badge variant="secondary" className="text-[10px]">6 sessions</Badge></div><div className="mt-6 flex h-[154px] items-end justify-between gap-2 border-b border-border pb-1">{[{ day: "M", height: 42 }, { day: "T", height: 57 }, { day: "W", height: 49 }, { day: "T", height: 72 }, { day: "F", height: 66 }, { day: "S", height: 87 }].map((bar, i) => <div key={i} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><span className="text-[9px] text-muted-foreground">{(6.4 + i * 0.33).toFixed(1)}</span><div className={`w-full max-w-9 rounded-t-md ${i === 5 ? "bg-primary" : "bg-primary/35"}`} style={{ height: `${bar.height}%` }} /><span className="text-[10px] text-muted-foreground">{bar.day}</span></div>)}</div><div className="mt-4 flex items-center gap-2 text-xs text-success"><TrendingUp size={14} /> Trending upward <span className="ml-auto text-muted-foreground">+18% this month</span></div></section>
    </div>
    <div className="grid gap-4 lg:grid-cols-2"><section className="surface flex items-center gap-4 p-5"><div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-chart-4/15 text-chart-4"><Target size={21} /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold">Placement prep checklist</p><p className="mt-1 text-xs text-muted-foreground">Two focus areas are ready for your next session.</p></div><Button variant="ghost" size="icon" aria-label="Open coaching" onClick={() => onPage("Coaching")}><ArrowRight /></Button></section><section className="surface flex items-center gap-4 p-5"><div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-success/15 text-success"><BookOpen size={21} /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold">Coach’s pick for today</p><p className="mt-1 text-xs text-muted-foreground">Practice explaining your approach out loud.</p></div><Button variant="ghost" size="icon" aria-label="View coaching" onClick={() => onPage("Coaching")}><ArrowRight /></Button></section></div>
  </div>;
}

function NewInterview({ config, setConfig, error, onStart }: { config: InterviewConfig; setConfig: (config: InterviewConfig) => void; error: string; onStart: () => void }) {
  const update = (key: keyof InterviewConfig, value: string) => setConfig({ ...config, [key]: value });
  return <div className="mx-auto max-w-[900px]"><SectionHeading eyebrow="Practice setup" title="Build your interview" action={<DemoTag />} /><div className="grid gap-5 lg:grid-cols-[1.5fr_0.8fr]"><section className="surface p-5 sm:p-7"><div className="mb-6"><h3 className="text-sm font-semibold">Interview details</h3><p className="mt-1 text-xs text-muted-foreground">Tailor your practice to the opportunity you're preparing for.</p></div><div className="space-y-6"><div><label className="mb-2 block text-xs font-medium">Company <span className="text-destructive">*</span></label><div className="grid grid-cols-2 gap-2 sm:grid-cols-3">{companies.map((company) => <button key={company} onClick={() => update("company", company)} aria-pressed={config.company === company} className={`flex min-h-12 items-center gap-2.5 rounded-lg border px-3 text-left text-xs font-medium transition-colors ${config.company === company ? "border-primary bg-primary/10 text-foreground" : "border-border bg-background/30 text-muted-foreground hover:border-primary/50 hover:text-foreground"}`}><span className={`flex size-7 shrink-0 items-center justify-center rounded-md text-[10px] font-bold ${config.company === company ? "bg-primary/20 text-primary" : "bg-muted text-muted-foreground"}`}>{company.slice(0, 1)}</span><span className="truncate">{company}</span>{config.company === company && <Check size={14} className="ml-auto shrink-0 text-primary" />}</button>)}</div></div><div><label className="mb-2 block text-xs font-medium">Role <span className="text-destructive">*</span></label><Select value={config.role} onValueChange={(value) => update("role", value)}><SelectTrigger aria-label="Role"><SelectValue placeholder="Select a role" /></SelectTrigger><SelectContent>{roles.map((role) => <SelectItem value={role} key={role}>{role}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-5 sm:grid-cols-2"><div><label className="mb-2 block text-xs font-medium">Difficulty</label><div className="flex rounded-lg border border-border bg-background/30 p-1">{["Easy", "Medium", "Hard", "Mixed"].map((level) => <button key={level} onClick={() => update("difficulty", level)} aria-pressed={config.difficulty === level} className={`flex-1 rounded-md px-1 py-2 text-[10px] font-medium transition-colors ${config.difficulty === level ? "bg-primary/20 text-primary" : "text-muted-foreground hover:text-foreground"}`}>{level}</button>)}</div></div><div><label className="mb-2 block text-xs font-medium">Number of questions</label><Select value={config.count} onValueChange={(value) => update("count", value)}><SelectTrigger aria-label="Number of questions"><SelectValue /></SelectTrigger><SelectContent>{Array.from({ length: 8 }, (_, i) => String(i + 3)).map((num) => <SelectItem value={num} key={num}>{num} questions</SelectItem>)}</SelectContent></Select></div></div>{error && <p role="alert" className="text-xs text-destructive">{error}</p>}<Button onClick={onStart} size="lg" className="w-full gap-2"><Mic2 size={16} /> Start interview <ArrowRight size={16} /></Button></div></section><aside className="space-y-4"><div className="surface p-5"><div className="flex size-10 items-center justify-center rounded-xl bg-primary/15 text-primary"><Sparkles size={19} /></div><h3 className="mt-4 text-sm font-semibold">Your session includes</h3><ul className="mt-4 space-y-3">{["Company-specific question style", "A mix of technical & behavioral", "Instant demo feedback", "Session recap in your reports"].map((item) => <li key={item} className="flex items-start gap-2.5 text-xs leading-5 text-muted-foreground"><Check size={14} className="mt-0.5 shrink-0 text-success" />{item}</li>)}</ul></div><div className="rounded-xl border border-warning/25 bg-warning/5 p-4"><div className="flex gap-2.5"><CircleHelp size={15} className="mt-0.5 shrink-0 text-warning" /><p className="text-[11px] leading-5 text-muted-foreground"><span className="font-semibold text-warning">Demo experience.</span> Questions and evaluation are sample frontend interactions, not a live AI interview.</p></div></div></aside></div></div>;
}

function InterviewRoom({ config, question, questionNumber, total, answer, setAnswer, error, history, onSubmit, onSkip, onEnd }: { config: InterviewConfig; question: string; questionNumber: number; total: number; answer: string; setAnswer: (answer: string) => void; error: string; history: Session[]; onSubmit: () => void; onSkip: () => void; onEnd: () => void }) {
  const progress = Math.min((questionNumber - 1) / total * 100, 100);
  return <div className="mx-auto max-w-[1000px]"><div className="mb-7 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><div className="flex size-11 items-center justify-center rounded-xl bg-primary/15 text-primary"><span className="text-sm font-bold">{config.company.slice(0, 1) || "M"}</span></div><div><p className="text-sm font-semibold">{config.company} <span className="text-muted-foreground">·</span> {config.role}</p><p className="mt-1 text-[11px] text-muted-foreground">{config.difficulty} practice <span className="mx-1">·</span> {total} questions</p></div></div><Button variant="outline" size="sm" onClick={onEnd} className="gap-2 text-xs"><X size={14} /> End interview</Button></div><div className="mb-6"><div className="mb-2 flex justify-between text-[11px]"><span className="text-muted-foreground">Interview progress</span><span className="font-medium">Question {questionNumber} <span className="text-muted-foreground">of {total}</span></span></div><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${progress}%` }} /></div></div><div className="grid gap-5 lg:grid-cols-[1fr_260px]"><div className="space-y-4"><section className="surface p-5 sm:p-7"><div className="mb-5 flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-full bg-primary/15 text-primary"><BrainCircuit size={19} /></div><div><p className="text-xs font-semibold">Your interviewer</p><p className="mt-1 flex items-center gap-1.5 text-[10px] text-success"><span className="size-1.5 rounded-full bg-success" /> Ready when you are</p></div><Badge variant="outline" className="ml-auto">DEMO</Badge></div><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-primary">Question {questionNumber}</p><h2 className="mt-3 text-xl font-medium leading-8 sm:text-2xl">{question}</h2><div className="mt-7"><label htmlFor="answer" className="mb-2 block text-xs font-medium">Your answer</label><Textarea id="answer" value={answer} onChange={(event) => setAnswer(event.target.value)} placeholder="Take a moment to structure your thoughts, then write your answer here…" className="min-h-[190px] resize-y border-border/80 bg-background/40 text-sm leading-6" /><div className="mt-2 flex items-center justify-between text-[10px] text-muted-foreground"><span>Consider sharing your approach, reasoning, and outcome.</span><span>{answer.length} characters</span></div></div>{error && <p role="alert" className="mt-3 text-xs text-destructive">{error}</p>}<div className="mt-5 flex flex-wrap items-center justify-between gap-3"><Button variant="ghost" size="sm" onClick={onSkip} className="gap-1 text-xs text-muted-foreground"><ChevronRight size={15} /> Skip question</Button><Button onClick={onSubmit} className="gap-2"><Check size={15} /> Submit answer</Button></div></section></div><aside className="space-y-4"><section className="surface p-4"><div className="flex items-center gap-2"><Clock3 size={15} className="text-primary" /><h3 className="text-xs font-semibold">Session overview</h3></div><div className="mt-4 space-y-3">{[["Answered", String(history.length)], ["Remaining", String(Math.max(0, total - history.length))], ["Role", config.role || "Not set"]].map(([key, value]) => <div key={key} className="flex items-center justify-between gap-2 border-t border-border/70 pt-3 text-[11px]"><span className="text-muted-foreground">{key}</span><span className="max-w-[140px] truncate font-medium">{value}</span></div>)}</div></section><section className="surface p-4"><div className="flex items-center gap-2"><MessageSquareText size={15} className="text-chart-4" /><h3 className="text-xs font-semibold">Conversation</h3><span className="ml-auto text-[10px] text-muted-foreground">{history.length}</span></div>{history.length ? <div className="mt-3 space-y-3">{history.slice(-2).map((entry, i) => <div key={`${entry.question}-${i}`} className="border-t border-border/70 pt-3"><p className="line-clamp-2 text-[10px] leading-4 text-muted-foreground">{entry.question}</p><p className="mt-1 text-[10px] text-success">Score: {entry.score}/10</p></div>)}</div> : <p className="mt-3 border-t border-border/70 pt-3 text-[10px] leading-5 text-muted-foreground">Your answered questions and feedback will appear here.</p>}</section><div className="rounded-xl border border-warning/25 bg-warning/5 p-4"><p className="text-[10px] leading-5 text-muted-foreground">Demo questions are sample prompts. Speak your answer aloud for realistic practice.</p></div></aside></div></div>;
}

function Evaluation({ session, config, questionNumber, total, onNext }: { session: Session | null; config: InterviewConfig; questionNumber: number; total: number; onNext: () => void }) {
  const score = session?.score ?? 7.8;
  const breakdown = [{ label: "Correctness", value: Math.min(9.5, score + 0.3), color: "bg-success" }, { label: "Depth", value: Math.max(5.5, score - 0.6), color: "bg-primary" }, { label: "Communication", value: Math.min(9.7, score + 0.1), color: "bg-chart-4" }];
  return <div className="mx-auto max-w-[1000px]"><SectionHeading eyebrow="Answer review" title={`Question ${questionNumber} feedback`} action={<DemoTag />} /><div className="grid gap-5 lg:grid-cols-[1fr_270px]"><div className="space-y-5"><section className="surface p-5 sm:p-6"><p className="text-[10px] font-semibold uppercase tracking-[0.15em] text-primary">Question</p><p className="mt-3 text-base font-medium leading-7">{session?.question ?? "Your answer feedback will appear here."}</p><div className="mt-5 border-t border-border pt-4"><p className="mb-2 text-[10px] font-semibold uppercase tracking-[0.15em] text-muted-foreground">Your response</p><p className="whitespace-pre-wrap text-xs leading-6 text-muted-foreground">{session?.answer ?? "Submit a practice answer to see a sample evaluation."}</p></div></section><section className="surface p-5 sm:p-6"><h3 className="text-sm font-semibold">Evaluation breakdown</h3><p className="mt-1 text-xs text-muted-foreground">Feedback is illustrative, based on a demo scoring rule.</p><div className="mt-5 space-y-5">{breakdown.map((item) => <div key={item.label}><div className="mb-2 flex justify-between text-xs"><span>{item.label}</span><span className="font-semibold">{item.value.toFixed(1)}<span className="text-muted-foreground"> / 10</span></span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${item.color}`} style={{ width: `${item.value * 10}%` }} /></div></div>)}</div></section><div className="grid gap-4 sm:grid-cols-2"><FeedbackCard title="What went well" icon={Check} color="text-success" points={["Clear structure made your response easy to follow.", "You addressed the core of the question."]} /><FeedbackCard title="Try next time" icon={Target} color="text-warning" points={["Add a concrete example or measurable outcome.", "Explain one trade-off behind your approach."]} /></div><div className="surface p-5"><p className="flex items-center gap-2 text-xs font-semibold"><Sparkles size={15} className="text-primary" /> Suggested follow-up</p><p className="mt-2 text-sm leading-6 text-muted-foreground">What alternative approach did you consider, and what would make you choose it?</p></div></div><aside className="space-y-4"><div className="surface p-5 text-center"><p className="text-xs font-medium text-muted-foreground">Overall score</p><p className="mt-4 text-5xl font-semibold tracking-tight">{score.toFixed(1)}<span className="text-lg text-muted-foreground">/10</span></p><Badge className="mt-3 border-success/20 bg-success/10 text-success hover:bg-success/10">Strong response</Badge><p className="mt-3 text-[10px] text-muted-foreground">{config.company} · {config.role}</p></div><section className="surface p-4"><p className="text-xs font-semibold">Session progress</p><p className="mt-1 text-[10px] text-muted-foreground">{questionNumber} of {total} answered</p><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(questionNumber / total * 100, 100)}%` }} /></div></section><Button onClick={onNext} className="w-full gap-2">{questionNumber >= total ? "View session report" : "Next question"}<ArrowRight size={15} /></Button></aside></div></div>;
}
function FeedbackCard({ title, icon: Icon, color, points }: { title: string; icon: typeof Check; color: string; points: string[] }) {
  return <section className="surface p-4"><h3 className={`flex items-center gap-2 text-xs font-semibold ${color}`}><Icon size={14} />{title}</h3><ul className="mt-3 space-y-2">{points.map((point) => <li key={point} className="text-[11px] leading-5 text-muted-foreground">{point}</li>)}</ul></section>;
}

function Coaching({ onReports }: { onReports: () => void }) {
  return <div><SectionHeading eyebrow="Personalized coaching" title="Your next steps" action={<DemoTag />} /><div className="mb-5 flex items-start gap-3 rounded-xl border border-primary/20 bg-primary/5 p-4"><Sparkles size={17} className="mt-0.5 shrink-0 text-primary" /><div><p className="text-xs font-semibold">A pattern worth working on</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Sample feedback [P1] and [P2] both suggest adding more specific examples and explaining the reasoning behind your decisions.</p></div></div><div className="grid gap-5 lg:grid-cols-2"><section className="surface p-5"><h3 className="flex items-center gap-2 text-sm font-semibold"><Code2 size={16} className="text-chart-4" /> Technical knowledge</h3><p className="mt-1 text-xs text-muted-foreground">Build sharper, more structured answers.</p><div className="mt-5 space-y-4">{[{ title: "System design fundamentals", text: "Practice breaking a problem into requirements, components, and trade-offs.", tag: "Focus area" }, { title: "Data structures & complexity", text: "State your time and space complexity, then discuss alternatives.", tag: "Keep practicing" }].map((item) => <div key={item.title} className="border-t border-border pt-4"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-semibold">{item.title}</p><Badge variant="secondary" className="text-[9px]">{item.tag}</Badge></div><p className="mt-2 text-[11px] leading-5 text-muted-foreground">{item.text}</p></div>)}</div></section><section className="surface p-5"><h3 className="flex items-center gap-2 text-sm font-semibold"><MessageSquareText size={16} className="text-success" /> Communication</h3><p className="mt-1 text-xs text-muted-foreground">Make your thought process easy to follow.</p><div className="mt-5 space-y-4">{[{ title: "Use a clear answer structure", text: "For experience questions, try Situation → Action → Result." }, { title: "Make outcomes concrete", text: "Include impact, constraints, or a metric wherever you can." }].map((item) => <div key={item.title} className="border-t border-border pt-4"><p className="text-xs font-semibold">{item.title}</p><p className="mt-2 text-[11px] leading-5 text-muted-foreground">{item.text}</p></div>)}</div></section></div><section className="surface mt-5 p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h3 className="text-sm font-semibold">Your five-day roadmap</h3><p className="mt-1 text-xs text-muted-foreground">A focused plan for your next practice week</p></div><Badge variant="outline">5 days</Badge></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">{[{ d: "01", t: "Tell your story", x: "Prepare two STAR-format examples." }, { d: "02", t: "Core concepts", x: "Review data structures and complexity." }, { d: "03", t: "Build a system", x: "Sketch one familiar product design." }, { d: "04", t: "Practice aloud", x: "Record a behavioral answer and review." }, { d: "05", t: "Run a mock", x: "Complete a timed company-focused round." }].map((item) => <div key={item.d} className="rounded-lg border border-border bg-background/40 p-3"><span className="text-[10px] font-bold text-primary">DAY {item.d}</span><p className="mt-2 text-xs font-semibold">{item.t}</p><p className="mt-1 text-[10px] leading-4 text-muted-foreground">{item.x}</p></div>)}</div><p className="mt-4 text-[10px] text-muted-foreground">General preparation suggestions. Sample feedback references [P1] and [P2] are illustrative demo data.</p></section><div className="mt-5 flex justify-end"><Button variant="outline" onClick={onReports} className="gap-2">Review reports <ArrowRight size={14} /></Button></div></div>;
}

function Reports({ config, history, searchTerm, setSearchTerm, toast, setToast }: { config: InterviewConfig; history: Session[]; searchTerm: string; setSearchTerm: (value: string) => void; toast: string; setToast: (value: string) => void }) {
  const company = config.company || "Google"; const role = config.role || "Software Developer";
  const visibleHistory = history.filter((entry) => entry.question.toLowerCase().includes(searchTerm.toLowerCase()));
  const reportMarkdown = `# MOCKMATE Practice Report\n\n> DEMO REPORT — sample frontend data, not generated by a live AI model.\n\n- Company: ${company}\n- Role: ${role}\n- Questions answered: ${history.length || 5}\n- Overall score: ${history.length ? (history.reduce((sum, item) => sum + item.score, 0) / history.length).toFixed(1) : "7.8"}/10\n\n## Strengths\n- Structured responses and clear communication.\n- Directly addressed the core question.\n\n## Focus areas\n- Add specific examples and measurable outcomes.\n- Explain trade-offs and alternatives.\n\n## Five-day improvement plan\n1. Prepare two STAR-format stories.\n2. Review data structures and complexity.\n3. Sketch a familiar product system.\n4. Practice one answer aloud.\n5. Complete a timed mock interview.\n\n## Question-wise evaluation\n${history.length ? history.map((item, i) => `\n${i + 1}. ${item.question}\n   Demo score: ${item.score}/10`).join("") : "\nNo live session in this demo yet; sample results are shown."}\n`;
  const markdownDownload = () => {
    const blob = new Blob([reportMarkdown], { type: "text/markdown;charset=utf-8" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = "mockmate-practice-report.md"; a.click(); URL.revokeObjectURL(url); setToast("Markdown report downloaded.");
  };
  const printReport = () => {
    const printWindow = window.open("", "_blank", "noopener,noreferrer,width=860,height=720");
    if (!printWindow) { setToast("Allow pop-ups to print or save the report as PDF."); return; }
    printWindow.document.write(`<html><head><title>MOCKMATE Demo Report</title><style>body{font:15px Arial,sans-serif;max-width:760px;margin:40px auto;color:#202536;line-height:1.6}h1,h2{color:#31224a}.tag{color:#7451ad;font-weight:bold}.muted{color:#687086}li{margin:8px 0}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px;border-bottom:1px solid #ddd}@media print{body{margin:12mm}}</style></head><body><p class="tag">MOCKMATE · DEMO REPORT</p><h1>Interview practice report</h1><p class="muted">${company} · ${role} · ${history.length || 5} questions</p><h2>Overall performance</h2><p><strong>${history.length ? (history.reduce((sum, item) => sum + item.score, 0) / history.length).toFixed(1) : "7.8"}/10</strong> · Sample frontend score</p><h2>Question-wise evaluation</h2><table><tr><th>#</th><th>Question</th><th>Demo score</th></tr>${(history.length ? history : [{ question: questionBank[0], score: 7.8 }]).map((item, i) => `<tr><td>${i + 1}</td><td>${item.question}</td><td>${item.score}/10</td></tr>`).join("")}</table><h2>Strengths</h2><ul><li>Structured responses and clear communication.</li><li>Directly addressed the core question.</li></ul><h2>Focus areas</h2><ul><li>Add specific examples and measurable outcomes.</li><li>Explain trade-offs and alternatives.</li></ul><h2>Five-day improvement plan</h2><ol><li>Prepare two STAR-format stories.</li><li>Review data structures and complexity.</li><li>Sketch a familiar product system.</li><li>Practice one answer aloud.</li><li>Complete a timed mock interview.</li></ol><p class="muted">Demo report only. AI evaluation and report generation require backend integration.</p><script>window.onload=()=>window.print()</script></body></html>`);
    printWindow.document.close(); setToast("Print dialog opened. Choose Save as PDF to keep a copy.");
  };
  const average = history.length ? (history.reduce((sum, item) => sum + item.score, 0) / history.length).toFixed(1) : "7.8";
  return <div><SectionHeading eyebrow="Your progress" title="Interview reports" action={<div className="flex gap-2"><Button variant="outline" size="sm" onClick={markdownDownload} className="gap-2"><Download size={14} /> Markdown</Button><Button size="sm" onClick={printReport} className="gap-2"><Download size={14} /> Download PDF</Button></div>} />{toast && <div role="status" className="mb-4 rounded-lg border border-success/20 bg-success/10 px-4 py-2 text-xs text-success">{toast}</div>}<div className="mb-5 flex items-start gap-3 rounded-xl border border-warning/25 bg-warning/5 p-4"><CircleHelp size={16} className="mt-0.5 shrink-0 text-warning" /><p className="text-xs leading-5 text-muted-foreground"><span className="font-semibold text-warning">Demo report.</span> Scores and coaching are sample data. PDF uses your browser’s print dialog; live AI report generation needs a backend.</p></div><div className="grid gap-5 xl:grid-cols-[0.8fr_1.4fr]"><section className="surface p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-xs text-muted-foreground">Interview summary</p><h3 className="mt-2 text-lg font-semibold">{company} <span className="text-muted-foreground">·</span> {role}</h3></div><span className="flex size-9 items-center justify-center rounded-lg bg-primary/15 text-primary"><FileText size={17} /></span></div><div className="mt-6 border-t border-border pt-5"><p className="text-[10px] uppercase tracking-widest text-muted-foreground">Overall performance</p><div className="mt-2 flex items-baseline gap-2"><span className="text-4xl font-semibold">{average}</span><span className="text-sm text-muted-foreground">/10</span><Badge className="ml-auto border-success/20 bg-success/10 text-success hover:bg-success/10">On track</Badge></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-success" style={{ width: `${Number(average) * 10}%` }} /></div></div><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-lg bg-background/50 p-3"><p className="text-[10px] text-muted-foreground">Questions</p><p className="mt-1 text-lg font-semibold">{history.length || 5}</p></div><div className="rounded-lg bg-background/50 p-3"><p className="text-[10px] text-muted-foreground">Focus areas</p><p className="mt-1 text-lg font-semibold">2</p></div></div></section><section className="surface min-w-0 p-5 sm:p-6"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-sm font-semibold">Question-wise evaluation</h3><p className="mt-1 text-xs text-muted-foreground">Review feedback from each practice answer</p></div><div className="relative"><Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground" /><input aria-label="Search questions" value={searchTerm} onChange={(event) => setSearchTerm(event.target.value)} placeholder="Search questions" className="h-8 w-40 rounded-md border border-input bg-background pl-8 pr-2 text-[10px] outline-none focus:ring-1 focus:ring-ring" /></div></div><div className="overflow-x-auto"><table className="w-full min-w-[480px] text-left"><thead><tr className="border-y border-border text-[10px] text-muted-foreground"><th className="py-2.5 pr-3 font-medium">QUESTION</th><th className="px-3 py-2.5 font-medium">CATEGORY</th><th className="px-3 py-2.5 font-medium">SCORE</th><th className="px-3 py-2.5 font-medium">STATUS</th></tr></thead><tbody>{(history.length ? visibleHistory : [{ question: "Tell me about a project you are proud of.", score: 8.2 }, { question: "How would you approach a system design problem?", score: 7.6 }, { question: "Describe a time you solved a difficult bug.", score: 7.8 }]).map((item, i) => <tr key={`${item.question}-${i}`} className="border-b border-border/70 text-[11px]"><td className="max-w-[210px] py-3 pr-3 leading-5">{item.question}</td><td className="px-3 py-3 text-muted-foreground">{i % 2 ? "Technical" : "Behavioral"}</td><td className="px-3 py-3 font-semibold">{item.score}<span className="font-normal text-muted-foreground">/10</span></td><td className="px-3 py-3"><Badge variant="secondary" className="text-[9px]">Reviewed</Badge></td></tr>)}</tbody></table>{history.length > 0 && visibleHistory.length === 0 && <p className="py-8 text-center text-xs text-muted-foreground">No questions match that search.</p>}</div></section></div><div className="mt-5 grid gap-4 md:grid-cols-3"><ReportMini icon={Check} title="Strengths" text="Clear structure · Direct answers · Good communication" tone="text-success" /><ReportMini icon={ArrowDownRight} title="Focus areas" text="More specific examples · Explain trade-offs" tone="text-warning" /><ReportMini icon={Target} title="Five-day plan" text="Stories → concepts → system design → timed practice" tone="text-primary" /></div></div>;
}
function ReportMini({ icon: Icon, title, text, tone }: { icon: typeof Check; title: string; text: string; tone: string }) { return <div className="surface flex gap-3 p-4"><Icon size={16} className={`mt-0.5 shrink-0 ${tone}`} /><div><p className="text-xs font-semibold">{title}</p><p className="mt-1 text-[11px] leading-5 text-muted-foreground">{text}</p></div></div>; }

function UnderTheHood() {
  const [open, setOpen] = useState("Prompt design");
  const stack = [{ n: "01", title: "LLM Integration", desc: "Gemini", icon: Sparkles }, { n: "02", title: "Interactive GUI", desc: "Web application", icon: LayoutDashboard }, { n: "03", title: "Prompt Engineering", desc: "Few-shot · CoT · Reflection", icon: MessageSquareText }, { n: "04", title: "LangChain", desc: "Prompt templates · LCEL", icon: Code2 }, { n: "05", title: "Agentic RAG", desc: "Retrieval planning", icon: Search }, { n: "06", title: "Intent Routing", desc: "PRACTICE · EVALUATE · COACH · REPORT · OTHER", icon: Zap }, { n: "07", title: "Vector Database", desc: "ChromaDB", icon: Building2 }];
  const agents = [{ title: "Interviewer Agent", desc: "Delivers role- and company-aware practice prompts.", icon: MessageSquareText, color: "text-primary" }, { title: "Evaluator Agent", desc: "Reviews correctness, depth, and communication.", icon: Gauge, color: "text-chart-4" }, { title: "Coach Agent", desc: "Turns patterns into focused next steps.", icon: GraduationCap, color: "text-success" }, { title: "Report Agent", desc: "Organizes session outcomes into a clear recap.", icon: FileText, color: "text-warning" }];
  const details: Record<string, string> = { "Prompt design": "Few-shot examples demonstrate the desired answer structure. Chain-of-thought (CoT) is a prompting strategy; production interfaces should display useful summaries rather than private model reasoning. Reflection prompts can help check the answer before it is shown.", "Retrieval trace": "Demo trace: classify intent → identify company and role → retrieve relevant interview material from ChromaDB → assemble context for the selected agent. This screen displays an illustrative flow, not a live retrieval run.", "Intent routing": "PRACTICE starts an interview. EVALUATE reviews an answer. COACH surfaces recurring focus areas. REPORT summarizes a session. OTHER handles requests outside the preparation workflow." };
  return <div><SectionHeading eyebrow="Agentic AI project" title="Under the hood" action={<DemoTag />} /><div className="mb-5 rounded-xl border border-warning/25 bg-warning/5 p-4"><div className="flex gap-2.5"><ShieldCheck size={16} className="mt-0.5 shrink-0 text-warning" /><p className="text-xs leading-5 text-muted-foreground"><span className="font-semibold text-warning">Architecture preview.</span> Components describe the planned Python service and are not wired to live AI, LangChain, or ChromaDB in this frontend demo.</p></div></div><section className="surface p-5 sm:p-6"><div className="mb-5"><h3 className="text-sm font-semibold">System flow</h3><p className="mt-1 text-xs text-muted-foreground">A request moves through intent classification, retrieval, and specialized response.</p></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{architecture.map(({ step, title, detail, icon: Icon }, i) => <div key={title} className="relative rounded-lg border border-border bg-background/40 p-4"><div className="flex items-center justify-between"><span className="text-[10px] font-bold text-primary">{step}</span><Icon size={17} className="text-muted-foreground" /></div><p className="mt-4 text-xs font-semibold">{title}</p><p className="mt-1 text-[10px] leading-4 text-muted-foreground">{detail}</p>{i < architecture.length - 1 && <ArrowRight size={14} className="absolute -right-[10px] top-1/2 z-10 hidden -translate-y-1/2 text-primary xl:block" />}</div>)}</div><div className="mt-4 flex flex-wrap items-center justify-center gap-2 text-[10px] font-medium text-muted-foreground sm:gap-3">{["User Input", "Intent Router", "Retrieval Planner", "ChromaDB", "AI Agents", "Response"].map((step, i) => <span className="flex items-center gap-2" key={step}><span className={`rounded-md px-2.5 py-1.5 ${i === 4 ? "bg-primary/15 text-primary" : "bg-muted"}`}>{step}</span>{i < 5 && <ArrowRight size={12} />}</span>)}</div></section><section className="mt-5"><div className="mb-4"><h3 className="text-sm font-semibold">Specialist agents</h3><p className="mt-1 text-xs text-muted-foreground">Each agent focuses on one part of the prep experience.</p></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{agents.map(({ title, desc, icon: Icon, color }) => <div className="surface p-4" key={title}><div className={`flex size-9 items-center justify-center rounded-lg bg-muted ${color}`}><Icon size={17} /></div><p className="mt-3 text-xs font-semibold">{title}</p><p className="mt-1 text-[10px] leading-5 text-muted-foreground">{desc}</p></div>)}</div></section><section className="surface mt-5 divide-y divide-border px-5">{Object.entries(details).map(([title, text]) => <div key={title} className="py-4"><button className="flex w-full items-center justify-between gap-3 text-left" onClick={() => setOpen(open === title ? "" : title)} aria-expanded={open === title}><span className="text-xs font-semibold">{title}</span><ChevronDown size={15} className={`text-muted-foreground transition-transform ${open === title ? "rotate-180" : ""}`} /></button>{open === title && <p className="mt-3 max-w-4xl text-xs leading-6 text-muted-foreground">{text}</p>}</div>)}</section></div>;
}
function Settings() {
  return <div className="mx-auto max-w-[900px]"><SectionHeading eyebrow="Your workspace" title="Settings" /><section className="surface p-5 sm:p-6"><h3 className="text-sm font-semibold">Student profile</h3><p className="mt-1 text-xs text-muted-foreground">Your practice profile for this demo.</p><div className="mt-5 grid gap-4 sm:grid-cols-2"><ProfileField label="Name" value="Student" /><ProfileField label="Role" value="Engineering Student" /><ProfileField label="Preferred interview focus" value="Mixed practice" /><ProfileField label="Workspace" value="Placement preparation" /></div></section><section className="surface mt-5 p-5 sm:p-6"><h3 className="text-sm font-semibold">Demo environment</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">Interview history and preferences stay in temporary app state. Connect a backend to persist accounts, sessions, and generated reports.</p><div className="mt-4 flex items-center gap-2 text-xs text-warning"><span className="size-2 rounded-full bg-warning" /> Local demo · no account or backend connected</div></section></div>;
}
function ProfileField({ label, value }: { label: string; value: string }) { return <div><p className="text-[10px] font-medium text-muted-foreground">{label}</p><p className="mt-1.5 rounded-md border border-border bg-background/40 px-3 py-2.5 text-xs">{value}</p></div>; }
